// Additive evidence; legacy responses stay intact.
export const freshExplorer053=()=>({version:1,facetAnswers:{},fieldAnswers:{},professionAnswers:{},history:[]});
const validId=x=>typeof x==='string'&&/^[a-z0-9-]{1,120}$/.test(x),text=x=>typeof x==='string'?x.slice(0,1800):'';
const answer=a=>a&&typeof a==='object'?{...(Number.isInteger(a.value)&&a.value>=1&&a.value<=5||['unsure','unfamiliar','skipped'].includes(a.value)?{value:a.value}:{}),...(['yes','no','unsure','unfamiliar','skipped'].includes(a.response)?{response:a.response}:{}),...(Array.isArray(a.selected)?{selected:[...new Set(a.selected.filter(validId))].slice(0,40)}:{}),...(['none','unsure','unfamiliar','skipped'].includes(a.feedback)?{feedback:a.feedback}:{}),source:a.source==='profile-inferred'?'profile-inferred':'student',confidence:['high','medium','low'].includes(a.confidence)?a.confidence:'high',evidence:text(a.evidence),at:text(a.at),...(a.reviewHold?{reviewHold:text(a.reviewHold)}:{})}:null;
export function cleanExplorer053(raw){const out=freshExplorer053();if(raw?.version!==1)return out;for(const [id,a]of Object.entries(raw.facetAnswers||{}))if(validId(id)&&answer(a))out.facetAnswers[id]=answer(a);for(const key of ['fieldAnswers','professionAnswers'])for(const [field,qs]of Object.entries(raw[key]||{}))if(validId(field)){out[key][field]={};for(const[id,a]of Object.entries(qs||{}))if(validId(id)&&answer(a))out[key][field][id]=answer(a);}out.history=(Array.isArray(raw.history)?raw.history:[]).slice(-1000).filter(r=>validId(r.questionId)&&['facet','field','profession'].includes(r.kind)).map(r=>({kind:r.kind,scope:validId(r.scope)?r.scope:'all',questionId:r.questionId,before:answer(r.before),after:answer(r.after),at:text(r.at)}));return out;}
export function saveExplorerAnswer(s,{kind,scope='all',questionId,payload,at=new Date().toISOString()}){if(!validId(questionId)||!validId(scope)||!['facet','field','profession'].includes(kind))return false;const a=answer({...payload,at});if(!a)return false;s.explorer053??=freshExplorer053();const root=kind==='facet'?s.explorer053.facetAnswers:(s.explorer053[kind==='field'?'fieldAnswers':'professionAnswers'][scope]??={}),before=root[questionId]||null;root[questionId]=a;s.explorer053.history.push({kind,scope,questionId,before,after:structuredClone(a),at});s.explorer053.history=s.explorer053.history.slice(-1000);return true;}
